package com.wissenup.domain.communication.entity; import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="notices") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor
public class Notice { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="notice_id") private Long noticeId; @Column(name="organization_id") private Long organizationId; private String title; private String description; @Column(name="notice_type") private String noticeType; @Column(name="publish_date") private LocalDate publishDate; @Column(name="expiry_date") private LocalDate expiryDate; @Column(name="attachment_url") private String attachmentUrl; private String status; @Column(name="created_at") private LocalDateTime createdAt; @Column(name="created_by") private Long createdBy; @Column(name="updated_at") private LocalDateTime updatedAt; @Column(name="updated_by") private Long updatedBy; @PrePersist void create(){if(status==null)status="ACTIVE";if(createdAt==null)createdAt=LocalDateTime.now();}@PreUpdate void update(){updatedAt=LocalDateTime.now();} }
